import{z as m,x as E,o as t,c as A,q as l,j as o,D as e,d as i,s,S as p,b as n}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"PRO / Preference Ranking Optimization","description":"","frontmatter":{"title":"PRO / Preference Ranking Optimization","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pro-rank.md","filePath":"llm/pro-rank.md","lastUpdated":1791063341000}'),P={name:"llm/pro-rank.md"};function R(d,a,h,c,B,u){const r=E("Mermaid");return t(),A("div",null,[a[2]||(a[2]=l('<h1 id="pro-preference-ranking-optimization" tabindex="-1">PRO / Preference Ranking Optimization <a class="header-anchor" href="#pro-preference-ranking-optimization" aria-label="Permalink to &quot;PRO / Preference Ranking Optimization&quot;">​</a></h1><div class="epigraph"><p>不要把一条长度为 n 的人类排序切成若干对再分别做 Bradley–Terry：按名次递推，每次把当前最好的与后面所有回答做一次一对多对比，直到排完。</p><footer>—— Song, Yu, Li, Yu, Huang, Li, Wang，Preference Ranking Optimization for Human Alignment，AAAI 2024</footer></div><p>成对方法把多次采样的信息收成 \\(y^1\\succ y^2\\)。更长的序若再被切成对，名次之间的全局结构消失：第三名与第五名的差距、第一名相对其余全体的独占，都进不了同一条归一化。Song 等人提出 Preference Ranking Optimization（PRO）：把任意长度的偏好排序写成类似 Plackett–Luce 的递推一对多对比，用长度平均对数概率当 \\(r_\\pi\\)，再加一项对第一名的 SFT。本篇写 AAAI 2024 原文如何从 BT 扩到 listwise、动态温度如何用 RM 分数拉开「略差」与「很差」，以及加长排序（混入 ChatGPT 回答）时他们声称的收益。成对退化（\\(n=2\\)）时 PRO 仍是一对一对比，但推导目标是 \\(n\\gt 2\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RLHF 被批评为相对 SFT 更不稳、更吃超参；与此同时，它真正有用的部分往往是「从语言空间里多采、多看」。多数直接偏好方法把这次多采立刻压回成对：DPO、RRHF 的铰链、SLiC 都主要在对上操作。\\(n\\) 条有全序时，切成对会丢失宏观对比——第一名应同时压过其余 \\(n-1\\) 条，而不是只压过相邻那一条。作者把对齐重述为：让模型给这 \\(n\\) 条的平均对数概率排序，与人类（或 RM）的排序一致。</p><p><span class="marginnote">直觉类比：切成对的损失像只记录相邻名次胜负的小组赛，第三和第五差多少、冠军领先全体多少，都进不了同一张记分表；listwise 像完整的排行榜——每轮拿当前第一名和剩下所有人同场比，全局名次结构写进同一个归一化里。</span></p><p>SFT 只拟合第一名，等于扔掉负例。BoN（只对最高分做 SFT）同样浪费其余名次。需要一种仍在监督设置下、一次前向吃完整条序的损失，并且 \\(n=2\\) 时回到熟悉的成对 logistic，以便和 DPO 对照。</p><h3 id="一对多不是-infonce-随便套用" tabindex="-1">一对多不是 InfoNCE 随便套用 <a class="header-anchor" href="#一对多不是-infonce-随便套用" aria-label="Permalink to &quot;一对多不是 InfoNCE 随便套用&quot;">​</a></h3><p>把第一名当正、其余当负，写成</p> \\[-\\log\\frac{\\exp r(y^1)}{\\sum_{i=1}^n\\exp r(y^i)} \\]<p>只刻画 \\(y^1\\succ\\{y^2,\\ldots,y^n\\}\\)，后面 \\(n-2\\) 段子序被丢掉。PRO 的关键是<strong>递推</strong>：丢掉当前第一，对剩余列表再写同样的一对多，直到只剩最后一名。这才用满全序，也才和 Plackett–Luce 的逐位置选择概率同构。</p><p><span class="marginnote">PL 模型通常在固定候选上聚合多张排序表。PRO 的每条提示候选不同，参数是整个 LM，理论上对应无限候选。\\(n\\) 增大是在用有限样本逼近「对语言空间的序」；它不是把词表上所有句子真的排一遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>人类或 RM 给出 \\(y^1\\succ y^2\\succ\\cdots\\succ y^n\\)。策略分数为长度平均对数概率</p> \\[r_\\pi(x,y^k)=\\frac{1}{|y^k|}\\sum_t\\log P(y^k_t\\mid x,y^k_{\\lt t}). \\]<p>listwise 项为</p> \\[\\mathcal{L}=-\\log\\prod_{k=1}^{n-1}\\frac{\\exp\\bigl(r_\\pi(x,y^k)\\bigr)}{\\sum_{i=k}^n\\exp\\bigl(r_\\pi(x,y^i)\\bigr)}, \\]<p>总损失 \\(\\mathcal{L}+\\beta\\mathcal{L}_{\\mathrm{SFT}}\\)，\\(\\mathcal{L}_{\\mathrm{SFT}}\\) 只加在第一名。原文把 \\(\\beta\\) 设成随排序长度变化的系数（如 \\(0.05(n-1)^2\\) 量级，以论文为准），避免 \\(n\\) 变大时对比项完全压过语言建模。</p><h3 id="接到-rm-上的动态温度" tabindex="-1">接到 RM 上的动态温度 <a class="header-anchor" href="#接到-rm-上的动态温度" aria-label="Permalink to &quot;接到 RM 上的动态温度&quot;">​</a></h3><p>均匀对待所有负例不合理：略差的 \\(y^{k+1}\\) 与差很多的 \\(y^n\\) 应受不同惩罚。作者用另一个 \\(r_\\phi\\) 的分数定义温度</p> \\[\\mathcal{T}^i_k=\\frac{1}{r_\\phi(x,y^k)-r_\\phi(x,y^i)}\\quad(i\\gt k), \\]<p>正例温度取负例温度的最小，以免分子分母失衡。分差大则温度低、对比更锋利。消融表明：去掉 SFT、只靠动态温度时收益更明显；与 SFT 联合时仍有增益。没有可靠 \\(r_\\phi\\) 时，退回均匀温度，损失仍是递推 PL。</p><p><span class="marginnote">数字实例：温度 \\(\\mathcal{T}^i_k=1/(r_\\phi(y^k)-r_\\phi(y^i))\\)——设第一名 0.9。某负例只有 0.1，分差 0.8，温度约 1.25，惩罚温和；另一负例 0.85，分差只有 0.05，温度高达 20，对比骤然锋利。效果是：贴着第一名的「很像」负例被重点打压，烂负例轻轻带过。</span></p>',23)),(t(),o(p,null,{default:e(()=>[s(r,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORD%5B%22%E5%85%A8%E5%BA%8F%20y1%20%E2%89%BB%20y2%20%E2%89%BB%20%E2%80%A6%20%E2%89%BB%20yn%22%5D%20--%3E%20PL%5B%22%E9%80%92%E6%8E%A8%E4%B8%80%E5%AF%B9%E5%A4%9A%EF%BC%9Ak%20vs%20%7Bk%E2%80%A6n%7D%22%5D%0A%20%20ORD%20--%3E%20SFT%5B%22%E7%AC%AC%E4%B8%80%E5%90%8D%20NLL%22%5D%0A%20%20RM%5B%22%E5%8F%AF%E9%80%89%20r%CF%86%22%5D%20--%3E%20T%5B%22%E5%8A%A8%E6%80%81%E6%B8%A9%E5%BA%A6%22%5D%0A%20%20T%20--%3E%20PL%0A%20%20PL%20--%3E%20PRO%5B%22L_PRO%22%5D%0A%20%20SFT%20--%3E%20PRO%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h3",{id:"加长排序的实验叙事",tabindex:"-1"},[i("加长排序的实验叙事 "),n("a",{class:"header-anchor",href:"#加长排序的实验叙事","aria-label":'Permalink to "加长排序的实验叙事"'},"​")],-1)),a[4]||(a[4]=n("p",null,"数据是 HH-RLHF 四份子集，可用 Alpaca 或 ChatGPT 增补候选，再用 \\(\\mathrm{RM}_{\\mathrm{train}}\\) 重排，得到长度 3–5 的序；评估用另一份 RM、BLEU、GPT-4 与人类，避免训评同一 RM。叙事有三条。\\(n=2\\) 时 PRO 已超过同设定的 SFT、RLHF、CoH、DPO、RRHF 的部分奖励列（以原文 Table 1 为准）。\\(n\\) 再加长，多数策略上升；混入高质量 ChatGPT 回答时，7B 模型的代理奖励可接近 ChatGPT 那一列——这是蒸馏上限，不是 7B 获得同等世界知识。异构来源（Curie + Alpaca + ChatGPT）往往优于同一弱模型重复采样，负例的多样性帮助模型看见「不该做的行为」。",-1)),a[5]||(a[5]=n("p",null,"RRHF 在长序上变弱，被作者归因于它仍是成对铰链，抓不住全局归一。BoN 在高质量增补后变强，因为第一名已经很好，只拟合它也够用；PRO 的论点是其余名次仍有信息。GPT-4 / 人类 pairwise 相对数据集 golden 并非全胜，Helpful-online 子集上会输，说明代理奖励与人的分歧仍在。",-1)),a[6]||(a[6]=n("h2",{id:"机制",tabindex:"-1"},[i("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=n("p",null,[i("递推 PL 让每个位置都做一次「在剩余集合里被选中」的 logistic 归一，梯度同时抬当前名次、压后面所有更差的，且经过同一 softmax 互相制约，避免成对铰链那种「只保证相邻序」的局部满足。平均对数概率与 RRHF / SimPO 同族，无参考模型。SFT 项保护流畅。动态温度把 RM 的"),n("strong",null,"标量差"),i("写回对比强度：若 \\(r_\\phi\\) 本身偏长度，温度会把长度差放大成更锋利的序，偏差被加重而不是被中和。")],-1)),(t(),o(p,null,{default:e(()=>[s(r,{id:"mermaid-75",class:"mermaid",graph:"flowchart%20TD%0A%20%20L0%5B%22%E5%88%97%E8%A1%A8%3A%20y1%2C%20y2%2C%20y3%2C%20y4%22%5D%20--%3E%20R1%5B%22%E7%AC%AC%201%20%E8%BD%AE%3A%20y1%20%E5%AF%B9%E6%AF%94%E5%89%A9%E4%BD%99%E5%85%A8%E9%83%A8%22%5D%0A%20%20R1%20--%3E%20D1%5B%22%E5%8E%BB%E6%8E%89%20y1%22%5D%0A%20%20D1%20--%3E%20R2%5B%22%E7%AC%AC%202%20%E8%BD%AE%3A%20y2%20%E5%AF%B9%E6%AF%94%20y3%20%E4%B8%8E%20y4%22%5D%0A%20%20R2%20--%3E%20D2%5B%22%E5%8E%BB%E6%8E%89%20y2%22%5D%0A%20%20D2%20--%3E%20R3%5B%22%E7%AC%AC%203%20%E8%BD%AE%3A%20y3%20%E5%AF%B9%E6%AF%94%20y4%22%5D%0A%20%20R3%20--%3E%20END%5B%22%E5%90%84%E8%BD%AE%E6%A6%82%E7%8E%87%E8%BF%9E%E4%B9%98%E5%BE%97%20listwise%20%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p>\\(n\\to\\infty\\) 的修辞是「看见更多带标签的语言空间样本」；实现上 \\(n\\) 受显存与标注费限制。把 ChatGPT 塞进序，是在用教师覆盖学生达不到的区域，效果一部分来自模仿教师，一部分来自 listwise 对比。消融必须分开「更好的第一名」与「更好的 listwise 结构」。</p><p><span class="marginnote">\\(\\beta\\) 随 \\(n\\) 涨，是为了让第一名 NLL 不被 \\(n-1\\) 个 softmax 项淹没。若不调 \\(\\beta\\)，加长排序可能只在对比上过拟合 RM，流畅性掉。监控应分列 SFT 项与 PL 项。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>PRO 需要全序或至少可排的 \\(n\\) 条。只有成对时，\\(n=2\\)，优势主要来自平均对数概率 + SFT，而不是 listwise。增补候选要花钱或调用教师；用 \\(\\mathrm{RM}_{\\mathrm{train}}\\) 排序则把 RM 偏差写进序。LLaMA-7B、HH、生成 128 token 的设定不能外推到长思维链。BLEU 在对话上弱，原文同时报奖励与裁判，读的人应以后者为准。</p><p><span class="marginnote">常见误区：初学者容易以为排序越长（\\(n\\) 越大）效果一定越好。\\(n\\) 每加一档，就多一批要标注或要调教师的候选，而且原文把 \\(\\beta\\) 设成随 \\(n\\) 增大——不调它，SFT 项会被 \\(n-1\\) 个对比项淹没，流畅性反而掉。\\(n\\) 是成本与收益的权衡，不是免费午餐。</span></p><p>与 DPO 比，PRO 无 \\(\\pi_{\\mathrm{ref}}\\)，有 SFT 项，吃 listwise。与 RRHF 比，损失是 softmax 归一而非无间隔铰链，对长序更一致。与 SimPO 比，SimPO 仍是成对加 \\(\\gamma\\)，PRO 是递推一对多。不要和「CPO / IPO」因缩写相近而混名。</p><p><span class="marginnote">出处钉 Feifan Song、Bowen Yu、Minghao Li、Haiyang Yu、Fei Huang、Yongbin Li、Houfeng Wang，北大与阿里，AAAI 2024，arXiv:2306.17492。代码在 AlibabaResearch/DAMO-ConvAI 的 PRO 目录。</span></p><h3 id="何时不必上-pro" tabindex="-1">何时不必上 PRO <a class="header-anchor" href="#何时不必上-pro" aria-label="Permalink to &quot;何时不必上 PRO&quot;">​</a></h3><p>只有成对、没有可靠多候选，DPO 或 SimPO 更轻。已有 \\(k\\) 条且满足于 Best-of-N 蒸馏，RRHF 或 BoN SFT 更简单。不能放平均对数概率、必须相对参照 KL 时，用 DPO。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PRO 把任意长度偏好排序写成递推一对多（Plackett–Luce 形），分数是长度平均对数概率，外加第一名 SFT。</li><li>\\(n=2\\) 退化为成对对比；收益声称随 \\(n\\) 与候选质量、多样性上升。</li><li>可用 RM 分数做动态温度，区分略差与很差。</li><li>长序实验大量依赖教师增补，部分效果是蒸馏。</li><li>相对 RRHF 的成对铰链，listwise 归一更能用满全序。</li><li>出处：Song et al.，<em>Preference Ranking Optimization for Human Alignment</em>，AAAI 2024。</li></ul>',11))])}const T=m(P,[["render",R]]);export{g as __pageData,T as default};
